-- Make anonymous report + leave atomic and refresh only a valid active session.
create or replace function public.report_and_leave_anonymous(target_session uuid,report_reason text) returns void language plpgsql security definer set search_path='' as $$ begin if not exists(select 1 from public.anonymous_sessions where id=target_session and status='active' and auth.uid() in(user_a,user_b)) then raise exception 'Active session required'; end if; insert into public.reports(reporter_id,target_user_id,reason,details) select auth.uid(),case when user_a=auth.uid() then user_b else user_a end,left(trim(report_reason),80),'anonymous session' from public.anonymous_sessions where id=target_session; update public.anonymous_sessions set status='ended',ended_at=now(),last_seen_at=now() where id=target_session; end; $$;
grant execute on function public.report_and_leave_anonymous(uuid,text) to authenticated;
